# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List

from rosterkit.models import Student
from operator import attrgetter

NAME_KEY = attrgetter("display_name")
SECTION_KEY = attrgetter("section")


def widest(values: Iterable[str]) -> int:
    """Length of the longest value in a column."""
    return max(len(value) for value in values)


def require_emails(students: List[Student]) -> None:
    """Refuse to build the sheet without every email."""
    for item in students:
        if not item.email:
            name = item.display_name
            raise ValueError(f"no email on file for {name}")


def format_contact_row(
    student: Student, name_width: int, section_width: int
) -> str:
    """Pad name, section and email to their widths."""
    name = f"{student.display_name:<{name_width}}"
    section = f"{student.section:<{section_width}}"
    return f"{name}  {section}  {student.email}"


def format_rows(students: List[Student]) -> List[str]:
    """Pad every row to the widest name and section."""
    name_width = widest(map(NAME_KEY, students))
    section_width = widest(map(SECTION_KEY, students))
    return [
        format_contact_row(item, name_width, section_width)
        for item in students
    ]


def contact_rows(students: Iterable[Student]) -> List[str]:
    """One aligned row per student, sorted by name."""
    ordered = sorted(students, key=NAME_KEY)
    if not ordered:
        raise ValueError("no students given")
    require_emails(ordered)
    return format_rows(ordered)
